hooks.command:
cd "$CLAUDE_PROJECT_DIR" 2>/dev/null && { echo '=== FlowStock session ==='; echo "Branch: $(git rev-parse --abbrev-ref HEAD 2>/dev/null)"; echo "HEAD:   $(git log -1 --pretty='%h %s' 2>/dev/null | head -c 80)"; CHANGED=$(git status --porcelain 2>/dev/null | wc -l | tr -d ' '); echo "Status: $CHANGED changed files"; echo; echo '=== Latest CI runs ==='; curl -s --max-time 5 'https://api.github.com/repos/lemon0333/flowstock/actions/runs?per_page=3' 2>/dev/null | python3 -c "import json,sys
import sys
try:
  d=json.load(sys.stdin)
  for r in d.get('workflow_runs',[])[:3]:
    sha=r['head_sha'][:7]; status=r['status']; conclusion=r['conclusion'] or '-'; title=(r['display_title'] or '')[:55]
    print(f'  {sha} {status:11} {conclusion:10} {title}')
except Exception:
  print('  (CI status unavailable)')" 2>/dev/null || echo '  (CI status unavailable)'; }
